<?php
require_once __DIR__.'/../../includes/bootstrap.php';
$pageTitle='Cetak Kartu QR';
if(!$pdo){http_response_code(500);require __DIR__.'/../../includes/header.php';echo '<div class="notice warning">Database belum tersambung.</div>';require __DIR__.'/../../includes/footer.php';exit;}
$jenis=(($_GET['jenis']??'siswa')==='guru')?'guru':'siswa';
$kelas=trim((string)($_GET['rombel']??''));
$kelasList=$pdo->query("SELECT DISTINCT rombel FROM siswa WHERE status='aktif' AND rombel IS NOT NULL AND TRIM(rombel)<>'' ORDER BY rombel")->fetchAll(PDO::FETCH_COLUMN);
if($jenis==='guru'){$q=$pdo->query("SELECT nama,nip AS kode,jabatan AS detail,'' AS rombel FROM guru WHERE status='aktif' AND nip IS NOT NULL AND TRIM(nip)<>'' ORDER BY nama");}
else{$sql="SELECT nama,COALESCE(NULLIF(TRIM(nisn),''),TRIM(nis)) AS kode,COALESCE(rombel,'') AS rombel FROM siswa WHERE status='aktif' AND ((nisn IS NOT NULL AND TRIM(nisn)<>'') OR (nis IS NOT NULL AND TRIM(nis)<>''))";$args=[];if($kelas!==''){$sql.=" AND rombel=?";$args[]=$kelas;}$sql.=" ORDER BY rombel,nama";$q=$pdo->prepare($sql);$q->execute($args);}
$people=$q->fetchAll();require __DIR__.'/../../includes/header.php';
?>
<section class="welcome no-print"><div><span class="eyebrow">KARTU IDENTITAS DIGITAL</span><h2>Cetak Kartu QR Code</h2><p>Cetak kartu absensi siswa dan guru dalam format A4.</p></div></section>
<section class="panel no-print" style="margin-bottom:16px"><form method="get" style="display:flex;gap:12px;align-items:end;flex-wrap:wrap"><label>Jenis kartu<select name="jenis" onchange="this.form.submit()"><option value="siswa" <?=$jenis==='siswa'?'selected':''?>>Siswa</option><option value="guru" <?=$jenis==='guru'?'selected':''?>>Guru</option></select></label><?php if($jenis==='siswa'):?><label>Kelas<select name="rombel"><option value="">Semua Kelas</option><?php foreach($kelasList as $k):?><option value="<?=h($k)?>" <?=$kelas===$k?'selected':''?>><?=h($k)?></option><?php endforeach;?></select></label><?php endif;?><button type="submit">Tampilkan</button><button type="button" onclick="window.print()">Cetak Semua Kartu</button></form><p style="margin-top:10px"><?=count($people)?> kartu tersedia. Data tanpa NISN/NIS/NIP tidak ditampilkan.</p></section>
<?php if(!$people):?><div class="notice warning">Tidak ada data aktif dengan identitas kartu yang valid.</div><?php else:?><div class="qr-grid"><?php foreach($people as $p):?><article class="qr-card"><header class="qr-head"><div class="qr-logo">SD</div><div><b>SDN CIBURAYUT 01</b><small>KARTU <?=strtoupper($jenis)?></small></div></header><h3><?=h($p['nama'])?></h3><p><?= $jenis==='guru'?'NIP: ':'NISN/NIS: ' ?><?=h($p['kode'])?></p><?php if($jenis==='siswa'):?><p>Kelas: <?=h($p['rombel']?:'-')?></p><?php elseif(!empty($p['detail'])):?><p><?=h($p['detail'])?></p><?php endif;?><div class="qr-code" data-code="<?=h($p['kode'])?>"></div><footer>SCAN UNTUK ABSENSI</footer></article><?php endforeach;?></div><?php endif;?>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>document.querySelectorAll('.qr-code').forEach(e=>{if(window.QRCode)new QRCode(e,{text:e.dataset.code,width:108,height:108,correctLevel:QRCode.CorrectLevel.M});else e.textContent='QR tidak termuat';});</script>
<style>
.qr-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.qr-card{background:#fff;border:1px solid #cbd5e1;border-radius:10px;padding:12px;text-align:center;color:#172033;break-inside:avoid}.qr-head{display:flex;align-items:center;gap:9px;text-align:left;border-bottom:1px solid #e2e8f0;padding-bottom:8px}.qr-logo{background:#e8efff;color:#3556cf;border-radius:8px;padding:10px;font-weight:900}.qr-head b,.qr-head small{display:block}.qr-head b{font-size:11px}.qr-head small{font-size:9px;color:#64748b}.qr-card h3{font-size:14px;margin:12px 0 5px}.qr-card p{font-size:11px;margin:4px}.qr-code{display:flex;justify-content:center;margin:10px}.qr-card footer{border-top:1px dashed #cbd5e1;padding-top:7px;font-size:9px;font-weight:800;letter-spacing:1px;color:#3556cf}@media(max-width:600px){.qr-grid{grid-template-columns:1fr}}@media print{@page{size:A4 portrait;margin:8mm}.sidebar,.topbar,.no-print,.footer{display:none!important}.main-area{margin:0!important;width:100%!important}.page-content{padding:0!important}.qr-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.qr-card{border:1px solid #888;padding:8px}.qr-code canvas,.qr-code img{width:88px!important;height:88px!important}}
</style>
